fn fibonacci(n: usize) -> Vec<i32> {
    // Create a vector with capacity n to avoid reallocations
    let mut result = Vec::with_capacity(n);
    
    // Handle the base cases
    if n >= 1 {
        result.push(0);  // F(0)
    }
    if n >= 2 {
        result.push(1);  // F(1)
    }
    
    // Generate the remaining Fibonacci numbers
    for i in 2..n {
        let next = result[i - 1] + result[i - 2];
        result.push(next);
    }
    
    result
}